export function findDuplicateTitles(notes: Note[]) {
  const seen = new Set<string>();
  const dupes = new Set<string>();
  for (const note of notes) {
    if (seen.has(note.title)) dupes.add(note.title);
    else seen.add(note.title);
  }
  return [...dupes];
}

